"""Generated by the NL to Flow Diagram Encoder Pipeline."""

class QueueUsingStacks:
    def __init__(self):
        self.stack_in = []
        self.stack_out = []

    def Enqueue(self, item):
        self.stack_in.append(item)

    def Dequeue(self):
        if (len(self.stack_out) == 0):
            while (not (len(self.stack_in) == 0)):
                temp = self.stack_in.pop(-1)
                self.stack_out.append(temp)
        if (len(self.stack_out) == 0):
            return 'Queue Empty'
        return self.stack_out.pop(-1)

q = QueueUsingStacks()

q.Enqueue(10)
q.Enqueue(20)
q.Enqueue(30)

print(q.Dequeue())   # 10
print(q.Dequeue())   # 20

q.Enqueue(40)
q.Enqueue(50)

print(q.Dequeue())   # 30
print(q.Dequeue())   # 40
print(q.Dequeue())   # 50
print(q.Dequeue())   # Queue Empty
